import json
from pathlib import Path
from collections import defaultdict

data=json.loads(Path('benchmark/source_data.json').read_text())
svcs={s['id']:s for s in data['microservices']['data']}
topics={t['topic_name']:t for t in data['kafka_topics']['data']}
flows=data['event_flows']['data']
# build lists
prod_edges=[]
cons_edges=[]
dlq_edges=[]
schema_edges=[]
for f in flows:
    if f['flow_type']=='produce':
        prod_edges.append((f['source'], f['target']))
    elif f['flow_type']=='consume':
        cons_edges.append((f['source'], f['target']))
    elif f['flow_type']=='dlq-produce':
        dlq_edges.append((f['source'], f['target']))
    elif f['flow_type']=='schema-lookup':
        schema_edges.append((f['source'], f['target']))

# Determine which topics consumed by which svc (consume edges use source svc, target topic?) let's inspect sample consume
for f in flows:
    if f['flow_type']=='consume':
        print('consume sample', f)
        break
